<section class="page-hero"><div class="container narrow"><p class="eyebrow">Contact</p><h1>Get in touch</h1><p>Use the form for product, order or general questions.</p></div></section><section class="section"><div class="container narrow panel"><form class="form-grid" method="post" action="/contact" id="form" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="name">Name</label><input id="name" name="name" type="text" autocomplete="name" maxlength="100" required value="<?=e((string)($formData['name']??''))?>"><?php if(isset($formErrors['name'])):?><span class="error"><?=e($formErrors['name'])?></span><?php endif;?></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required value="<?=e((string)($formData['email']??''))?>"><?php if(isset($formErrors['email'])):?><span class="error"><?=e($formErrors['email'])?></span><?php endif;?></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" minlength="20" maxlength="3000" required><?=e((string)($formData['message']??''))?></textarea><?php if(isset($formErrors['message'])):?><span class="error"><?=e($formErrors['message'])?></span><?php endif;?></div><div aria-hidden="true" style="position:absolute;left:-9999px"><label for="website">Website</label><input id="website" name="website" type="text" tabindex="-1" autocomplete="off"></div><?php if(isset($formErrors['form'])):?><p class="error" role="alert"><?=e($formErrors['form'])?></p><?php endif;?><button class="button primary" type="submit">Send message</button></form></div></section>
